(async () => {
      const redis = getRedisClient(env);
      if (!redis) {
        return {
          detail: "REDIS_URL not configured",
          label: "Redis",
          status: "yellow" as const,
          value: "Unavailable",
        };
      }

      const startedAt = Date.now();
      const pong = await runRedisOperation(
        env,
        "redis_ping",
        async (innerRedis) => await innerRedis.ping(),
        async () => "",
      );
      const latencyMs = Date.now() - startedAt;
      if (pong) {
        return {
          detail: `Latency ${latencyMs}ms`,
          label: "Redis",
          status: latencyMs > 400 ? "yellow" : "green",
          value: pong.toUpperCase(),
        } as const;
      }

      return {
        detail: isDependencyCircuitOpen("redis") ? "Circuit breaker open; running in degraded mode" : "Ping failed",
        label: "Redis",
        status: "red" as const,
        value: "Error",
      } as const;
    })
